  "knowledge": "Performance-Cost Efficiency Score",
  "description": "Calculates a fund's efficiency by measuring its annual outperformance relative to its cost compared to peers.",
  "definition": "\text{PCES} = \frac{\text{Annual Fund Outperformance}}{\text{Relative Expense Ratio}}"
}

{
  "id": 2,
  "knowledge": "Return on Cost (ROC)",
  "description": "Assesses the fund's one-year performance relative to its cost, indicating how much return is generated per unit of expense.",
  "definition": "ROC = \frac{\text{Fund's 1-year return}}{\text{Net expense ratio}}"
}

{
  "id": 0,
  "knowledge": "Annual Fund Outperformance",
  "description": "Calculates the excess return of a fund compared to its category benchmark for a given year.",
  "definition": "\text{Annual Fund Outperformance} = \text{Fund's annual return} - \text{Category's average annual return}"
}

{
  "id": 1,
  "knowledge": "Relative Expense Ratio",
  "description": "Measures the difference between a fund's net expense ratio and its benchmark's expense ratio.",
  "definition": "\text{Relative Expense} = \text{Fund's net expense ratio} - \text{Benchmark's expense ratio}"
}
